import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Reusable, 100% self-contained branding widget for Craftline Interactive.
///
/// Contains embedded vector-quality logo asset data directly in Dart code (ZERO external assets required in pubspec.yaml).
/// Completely portable: copy and paste this single file directly into any Flutter game or application.
class CraftlineLogo extends StatelessWidget {
  /// Overall width of the logo.
  final double width;

  /// Optional height. If null, scales proportionally with width.
  final double? height;

  const CraftlineLogo({
    super.key,
    this.width = 175.0,
    this.height,
  });

  // Lazily decoded bytes cached in memory
  static final Uint8List _logoBytes = base64Decode(_rawLogoBase64);

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _logoBytes,
      width: width,
      height: height,
      fit: BoxFit.contain,
      filterQuality: FilterQuality.high,
    );
  }

  static const String _rawLogoBase64 = '';
}
